"use client";

import { ParticleCanvas } from "@/components/custom/blocks/ParticleCanvasBlock";

export default function ParticleCanvasDemo() {
  return (
    <div className="relative w-full h-[650px] min-h-max bg-background rounded-xl overflow-hidden flex items-center justify-center border border-border">
      <ParticleCanvas
        variant="repel"
        content="AlgorizeTech"
        particleSize={2.5}
        particleGap={5}
        speed={1}
        className="w-full h-full min-h-[650px]"
      />
    </div>
  );
}

"use client";

import React, { useEffect, useRef, useCallback, useState, useSyncExternalStore } from "react";

/**
 * False while server-rendering and during hydration, true afterwards — without
 * the extra render an effect-flipped useState costs.
 */
const subscribeToNothing = () => () => {};
const useIsMounted = () =>
  useSyncExternalStore(
    subscribeToNothing,
    () => true,
    () => false,
  );

import { useTheme } from "next-themes";
import { cn } from "@/lib/utils";
import { accentStyle } from "@/lib/accent";

export interface ParticleCanvasProps extends React.HTMLAttributes<HTMLDivElement> {
  content?: string;
  variant?: "repel" | "wordmark-glow" | (string & {});
  particleSize?: number;
  particleGap?: number;
  speed?: number;
  color?: string;
  backgroundColor?: string;
  interactive?: boolean;
  fontSize?: number;
  fontFamily?: string;
  className?: string;
}

interface Particle {
  x: number;
  y: number;
  originX: number;
  originY: number;
  targetX: number;
  targetY: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  scatterSeed: number;
  forceMult: number;
}

const PRESET_ACCENT_HEX: Record<string, string> = {
  indigo: "#6366f1",
  rose: "#f43f5e",
  emerald: "#10b981",
  zinc: "#18181b",
  amber: "#f59e0b",
  blue: "#3b82f6",
};

/** Turns a preset accent name or custom hex string into a CSS color, or null for default theme. */
function resolveColorAccent(color?: string): string | null {
  if (!color || color === "primary" || color === "default") return null;
  return PRESET_ACCENT_HEX[color] ?? color;
}

const wordmarkGlowKeyframes = `
@keyframes particle-canvas-word-rise {
  from { transform: translateY(70%); }
  to { transform: none; }
}
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .particle-canvas-word-letter {
      animation: particle-canvas-word-rise linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--i) * 4%) entry 100%;
    }
  }
}
`;

export interface WordmarkGlowProps extends React.HTMLAttributes<HTMLDivElement> {
  content?: string;
  color?: string;
  className?: string;
}

export function WordmarkGlowCanvas({
  content = "AlgorizeTech",
  color,
  className,
  style,
  ...props
}: WordmarkGlowProps) {
  const wrapRef = useRef<HTMLDivElement>(null);

  // Writes pointer position as --mx / --my for the radial glow
  useEffect(() => {
    const node = wrapRef.current;
    if (!node || typeof window === "undefined" || !window.matchMedia("(hover: hover) and (pointer: fine)").matches) return undefined;
    let frame = 0;
    let x = 0;
    let y = 0;
    const onMove = (event: PointerEvent) => {
      const rect = node.getBoundingClientRect();
      x = event.clientX - rect.left;
      y = event.clientY - rect.top;
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        node.style.setProperty("--mx", `${x}px`);
        node.style.setProperty("--my", `${y}px`);
      });
    };
    node.addEventListener("pointermove", onMove);
    return () => {
      node.removeEventListener("pointermove", onMove);
      cancelAnimationFrame(frame);
    };
  }, []);

  const dynamicAccent = accentStyle(color);
  const charRatio = content ? Math.max(content.length * 0.56, 2.5) : 4.5;

  return (
    <div
      ref={wrapRef}
      style={{ ...dynamicAccent, ...style }}
      className={cn(
        "group/word relative isolate flex w-full h-full min-h-[450px] items-center justify-center overflow-hidden px-4 select-none bg-background text-foreground transition-colors [container-type:inline-size]",
        className
      )}
      {...props}
    >
      <style>{wordmarkGlowKeyframes}</style>

      {/* Glow behind the letters; follows mouse pointer and glows with active theme / primary color */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 -z-10 bg-[radial-gradient(380px_circle_at_var(--mx,50%)_var(--my,50%),color-mix(in_oklab,var(--primary)_45%,transparent),transparent_70%)] opacity-60 transition-opacity duration-300 group-hover/word:opacity-100"
      />

      <p
        aria-hidden="true"
        style={{
          fontSize: `clamp(3.5rem, calc(88cqi / ${charRatio}), 19rem)`,
        }}
        className="pointer-events-none flex w-full select-none justify-center whitespace-nowrap text-[clamp(3.5rem,calc(88vw/4.5),19rem)] font-semibold leading-[0.85] tracking-[-0.035em]"
      >
        {[...content].map((letter, index) => (
          <span
            key={index}
            style={{ "--i": index } as React.CSSProperties}
            className="particle-canvas-word-letter inline-block px-[0.02em] last:pr-[0.14em] bg-gradient-to-b from-foreground/25 to-foreground/[0.03] to-85% bg-clip-text text-transparent"
          >
            {letter}
          </span>
        ))}
      </p>
    </div>
  );
}

function StandardParticleCanvas({
  content = "AlgorizeTech",
  variant = "repel",
  particleSize = 2.5,
  particleGap = 5,
  speed = 1,
  color,
  backgroundColor = "transparent",
  interactive = true,
  fontSize,
  fontFamily = "system-ui, -apple-system, sans-serif",
  className,
  ...props
}: ParticleCanvasProps) {
  const { resolvedTheme } = useTheme();
  const mounted = useIsMounted();
  const [themePrimaryColor, setThemePrimaryColor] = useState<string>("currentColor");

  // Real-time semantic CSS theme color resolver (supports standard CSS vars and Shadcn HSL variables)
  const getActivePrimaryColor = (): string => {
    if (typeof window === "undefined") return resolvedTheme === "light" ? "#18181b" : "#3b82f6";
    try {
      // 1. Direct CSS variable evaluation
      const dummy = document.createElement("div");
      dummy.style.color = "var(--primary)";
      dummy.style.position = "absolute";
      dummy.style.visibility = "hidden";
      dummy.style.pointerEvents = "none";
      document.body.appendChild(dummy);
      let computedColor = window.getComputedStyle(dummy).color;
      document.body.removeChild(dummy);

      if (computedColor && computedColor !== "rgba(0, 0, 0, 0)" && computedColor !== "transparent") {
        return computedColor;
      }

      // 2. Shadcn HSL CSS variable format fallback (hsl(var(--primary)))
      const dummyHsl = document.createElement("div");
      dummyHsl.style.color = "hsl(var(--primary))";
      dummyHsl.style.position = "absolute";
      dummyHsl.style.visibility = "hidden";
      dummyHsl.style.pointerEvents = "none";
      document.body.appendChild(dummyHsl);
      computedColor = window.getComputedStyle(dummyHsl).color;
      document.body.removeChild(dummyHsl);

      if (computedColor && computedColor !== "rgba(0, 0, 0, 0)" && computedColor !== "transparent") {
        return computedColor;
      }
    } catch {
      // Colour could not be resolved; fallback used below
    }
    return resolvedTheme === "light" ? "#18181b" : "#3b82f6";
  };

  // Dynamically observe and resolve exact active site theme --primary CSS color variable
  useEffect(() => {
    if (typeof window === "undefined" || !mounted) return;

    const updateThemeColor = () => {
      const activeColor = getActivePrimaryColor();
      setThemePrimaryColor(activeColor);
    };

    updateThemeColor();

    const observer = new MutationObserver(() => updateThemeColor());
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "style", "data-theme"],
    });

    return () => observer.disconnect();
  }, [mounted, resolvedTheme]);

  // Resolve picked color from color picker or fallback to exact active header primary theme color
  const resolvedPickerColor = resolveColorAccent(color);
  const effectiveColor =
    resolvedPickerColor ||
    (themePrimaryColor !== "currentColor"
      ? themePrimaryColor
      : getActivePrimaryColor());

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const particlesRef = useRef<Particle[]>([]);
  const mouseRef = useRef<{ x: number; y: number; active: boolean }>({
    x: -9999,
    y: -9999,
    active: false,
  });

  const sampleParticles = useCallback(
    (width: number, height: number): Promise<{ x: number; y: number }[]> => {
      return new Promise((resolve) => {
        const offscreen = document.createElement("canvas");
        offscreen.width = width;
        offscreen.height = height;
        const ctx = offscreen.getContext("2d", { willReadFrequently: true });

        if (!ctx) {
          resolve([]);
          return;
        }

        const sampled: { x: number; y: number }[] = [];

        // Device Breakpoint Gap Rules:
        // Small (< 768px): gap = 3.0px
        // MD (768px - 1023px): gap = 4.0px
        // Large (>= 1024px): gap = 5.0px (or particleGap prop)
        let currentGap: number;
        if (width < 768) {
          currentGap = 3;
        } else if (width < 1024) {
          currentGap = 4;
        } else {
          currentGap = Math.max(2, Math.round(particleGap));
        }

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = "#000000";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";

        const calcFontSize = fontSize || Math.min((width * 0.92) / (content.length * 0.58), height * 0.42);
        ctx.font = `bold ${calcFontSize}px ${fontFamily}`;
        ctx.fillText(content, width / 2, height / 2);

        const imgData = ctx.getImageData(0, 0, width, height);
        const data = imgData.data;

        for (let y = 0; y < height; y += currentGap) {
          for (let x = 0; x < width; x += currentGap) {
            const index = (Math.floor(y) * width + Math.floor(x)) * 4;
            const alpha = data[index + 3];
            if (alpha > 128) {
              sampled.push({ x: Math.floor(x), y: Math.floor(y) });
            }
          }
        }
        resolve(sampled);
      });
    },
    [content, particleGap, fontSize, fontFamily]
  );

  const initParticles = useCallback(
    async (width: number, height: number) => {
      const targets = await sampleParticles(width, height);
      const newParticles: Particle[] = [];

      targets.forEach((target) => {
        newParticles.push({
          x: target.x,
          y: target.y,
          originX: target.x,
          originY: target.y,
          targetX: target.x,
          targetY: target.y,
          vx: 0,
          vy: 0,
          size: particleSize,
          color: effectiveColor,
          scatterSeed: (Math.random() - 0.5) * 0.7,
          forceMult: 0.6 + Math.random() * 0.8,
        });
      });

      particlesRef.current = newParticles;
    },
    [sampleParticles, particleSize]
  );

  // Update existing particles' color dynamically without resetting position/scatter
  useEffect(() => {
    particlesRef.current.forEach((p) => {
      p.color = effectiveColor;
    });
  }, [effectiveColor]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let width = (canvas.width = container.clientWidth);
    let height = (canvas.height = container.clientHeight);

    const handleResize = () => {
      if (!container || !canvas) return;
      width = canvas.width = container.clientWidth;
      height = canvas.height = container.clientHeight;
      initParticles(width, height);
    };

    const resizeObserver = new ResizeObserver(() => {
      handleResize();
    });
    resizeObserver.observe(container);

    initParticles(width, height);

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      if (backgroundColor && backgroundColor !== "transparent") {
        ctx.fillStyle = backgroundColor;
        ctx.fillRect(0, 0, width, height);
      }

      const particles = particlesRef.current;
      const mouse = mouseRef.current;

      // Device Breakpoint Size Rules:
      // Small (< 768px): particleSize = 1.5px
      // MD (768px - 1023px): particleSize = 2.0px
      // Large (>= 1024px): particleSize = 2.5px
      let currentParticleSize: number;
      let currentRadius: number;

      if (width < 768) {
        currentParticleSize = 1.5;
        currentRadius = 45;
      } else if (width < 1024) {
        currentParticleSize = 2.0;
        currentRadius = 65;
      } else {
        currentParticleSize = particleSize;
        currentRadius = 85;
      }

      // Lock global alpha to 1.0 for 100% solid, identical color brightness across ALL dots
      ctx.globalAlpha = 1.0;
      ctx.fillStyle = effectiveColor;

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];

        // Smooth fluid spring return to origin
        const dx = p.originX - p.x;
        const dy = p.originY - p.y;
        p.x += dx * 0.09 * speed;
        p.y += dy * 0.09 * speed;

        // Organic staggered repulsion force ("chorai chitai jabe")
        if (interactive && mouse.active) {
          const mdx = p.x - mouse.x;
          const mdy = p.y - mouse.y;
          const dist = Math.sqrt(mdx * mdx + mdy * mdy);

          if (dist < currentRadius) {
            const force = (currentRadius - dist) / currentRadius;
            // Add unique scatter angle perturbation and staggered velocity per particle
            const angle = Math.atan2(mdy, mdx) + p.scatterSeed * force;
            const push = force * 35 * p.forceMult * speed;
            p.x += Math.cos(angle) * push;
            p.y += Math.sin(angle) * push;
          }
        }

        // Render distinct circular particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, currentParticleSize, 0, Math.PI * 2);
        ctx.fill();
      }

      animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      resizeObserver.disconnect();
    };
  }, [initParticles, backgroundColor, speed, interactive, effectiveColor, particleSize]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current || !interactive) return;
    const rect = containerRef.current.getBoundingClientRect();
    mouseRef.current.x = e.clientX - rect.left;
    mouseRef.current.y = e.clientY - rect.top;
    mouseRef.current.active = true;
  };

  const handleMouseLeave = () => {
    mouseRef.current.active = false;
    mouseRef.current.x = -9999;
    mouseRef.current.y = -9999;
  };

  const handleTouchMove = (e: React.TouchEvent<HTMLDivElement>) => {
    if (!containerRef.current || !interactive || e.touches.length === 0) return;
    const rect = containerRef.current.getBoundingClientRect();
    mouseRef.current.x = e.touches[0].clientX - rect.left;
    mouseRef.current.y = e.touches[0].clientY - rect.top;
    mouseRef.current.active = true;
  };

  return (
    <div
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleMouseLeave}
      className={cn(
        "relative w-full h-full min-h-[600px] overflow-hidden select-none cursor-crosshair",
        className
      )}
      {...props}
    >
      <canvas ref={canvasRef} className="block w-full h-full" />
    </div>
  );
}

export function ParticleCanvas(props: ParticleCanvasProps) {
  if (props.variant === "wordmark-glow") {
    return <WordmarkGlowCanvas {...props} />;
  }
  return <StandardParticleCanvas {...props} />;
}

export default ParticleCanvas;

import type { CSSProperties } from "react";

/**
 * Bridging the docs colour picker into a preview.
 *
 * Most blocks are already written against the `--primary` token (`bg-primary`,
 * `ring-primary/30`, `text-primary-foreground`…). Rather than teaching each one a
 * bespoke `color` prop, a demo can repoint that token for its own subtree and
 * every one of those classes follows along.
 */

/** The swatches the picker offers, as concrete CSS colours. */
const PRESET_HEX: Record<string, string> = {
  lavender: "#9b8afb",
  indigo: "#6366f1",
  rose: "#f43f5e",
  emerald: "#10b981",
};

/** True when the picker sits on "Default" — the page theme should win. */
export function isDefaultAccent(color?: string): boolean {
  return !color || color === "primary" || color === "default";
}

/**
 * Turns a picker value into a CSS colour, or null for "Default" — meaning
 * nothing should be overridden, so the theme (and the sidebar customizer)
 * keeps control.
 */
export function resolveAccent(color?: string): string | null {
  if (isDefaultAccent(color)) return null;
  return PRESET_HEX[color as string] ?? (color as string);
}

/**
 * The picker value in a form every block accepts. Blocks know the older swatch
 * names but not "lavender" — and since that is also a CSS named colour
 * (#e6e6fa), a block that passes unknown names straight through would paint
 * the wrong shade, while others fall back to a different palette. Demos that
 * hand the picker value to such a block run it through this first. Every
 * other value is returned untouched.
 */
export function toBlockColor(color: string): string;
export function toBlockColor(color: string | undefined): string | undefined;
export function toBlockColor(color?: string): string | undefined {
  return color === "lavender" ? PRESET_HEX.lavender : color;
}

function parseHex(input: string): [number, number, number] | null {
  const hex = input.trim().replace(/^#/, "");
  if (/^[a-f\d]{3}$/i.test(hex)) {
    const [r, g, b] = hex.split("");
    return [parseInt(r + r, 16), parseInt(g + g, 16), parseInt(b + b, 16)];
  }
  if (/^[a-f\d]{6}$/i.test(hex)) {
    return [
      parseInt(hex.slice(0, 2), 16),
      parseInt(hex.slice(2, 4), 16),
      parseInt(hex.slice(4, 6), 16),
    ];
  }
  return null;
}

/** Legible foreground for content sitting on a filled `color` swatch. */
export function accentForeground(color: string): string {
  const rgb = parseHex(color);
  if (!rgb) return "#ffffff";
  const channel = (v: number) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  };
  const luminance =
    0.2126 * channel(rgb[0]) +
    0.7152 * channel(rgb[1]) +
    0.0722 * channel(rgb[2]);
  return luminance > 0.45 ? "#09090b" : "#ffffff";
}

/** The theme tokens a picked accent repoints, as `--name` → value. */
export function accentTokens(color?: string): Record<string, string> {
  const resolved = resolveAccent(color);
  if (!resolved) return {};
  return {
    "--primary": resolved,
    "--primary-foreground": accentForeground(resolved),
    "--ring": resolved,
  };
}

/**
 * Inline style repointing `--primary` at the picked accent for one subtree.
 * `--primary-foreground` is derived alongside it, otherwise a light pick leaves
 * `text-primary-foreground` content unreadable on its own fill. Returns `{}` on
 * "Default" so the page theme still wins.
 */
export function accentStyle(color?: string): CSSProperties {
  return accentTokens(color) as CSSProperties;
}
